<script setup>
import { computed, ref, onMounted, onUnmounted } from 'vue'
import { Plus, Search, Pencil, Trash2, X, CarFront, Users, Hash, Check } from 'lucide-vue-next'
import { readData, updateData, uid, addActivity } from '../services/storage'
function blank(){return {plate:'',model:'',type:'Sedan',capacity:4,status:'Available'}}
const tick=ref(0),search=ref(''),modal=ref(false),editing=ref(null),error=ref(''),success=ref(''),form=ref(blank())
const saving = ref(false)
const data=computed(()=>{tick.value;return readData()})
const rows=computed(()=>data.value.vehicles.filter(v=>[v.plate,v.model,v.type].some(x=>String(x).toLowerCase().includes(search.value.toLowerCase()))))
const refresh=()=>tick.value++
onMounted(()=>window.addEventListener('taxigo:data-updated',refresh));onUnmounted(()=>window.removeEventListener('taxigo:data-updated',refresh))
function open(v){editing.value=v?.id||null;form.value=v?{...v}:blank();error.value='';modal.value=true}
function save(){error.value='';if(saving.value)return;saving.value=true;const plate=form.value.plate.trim().toUpperCase();if(plate.length<3){error.value='Enter a valid plate number.';saving.value=false;return}if(!form.value.model.trim()){error.value='Enter the vehicle model.';saving.value=false;return}const cap=Number(form.value.capacity);if(!Number.isInteger(cap)||cap<1||cap>15){error.value='Capacity must be from 1 to 15.';saving.value=false;return}if(data.value.vehicles.some(v=>v.plate.toUpperCase()===plate&&v.id!==editing.value)){error.value='That plate number is already registered.';saving.value=false;return}if(form.value.status==='Maintenance'&&data.value.bookings.some(b=>['Confirmed','In Progress'].includes(b.status)&&b.vehicleId===editing.value)){error.value='This vehicle is assigned to an active ride.';saving.value=false;return}updateData(d=>{if(editing.value)Object.assign(d.vehicles.find(v=>v.id===editing.value),{...form.value,plate,capacity:cap,model:form.value.model.trim()});else d.vehicles.unshift({...form.value,id:uid('vehicle'),plate,capacity:cap,model:form.value.model.trim(),createdAt:new Date().toISOString()})});addActivity(`${editing.value?'Updated':'Added'} vehicle ${plate}`);modal.value=false;success.value='Vehicle record saved.';saving.value=false}
function remove(v){if(data.value.bookings.some(b=>['Confirmed','In Progress'].includes(b.status)&&b.vehicleId===v.id)){error.value='This vehicle is assigned to an active ride. Complete or cancel that ride first.';return}if(!confirm(`Remove vehicle ${v.plate}?`))return;updateData(d=>{d.vehicles=d.vehicles.filter(x=>x.id!==v.id)});success.value='Vehicle removed.';error.value=''}
</script>
<template><div class="page-heading"><div><div class="eyebrow">FLEET OPERATIONS</div><h1>Vehicle management</h1><p>Track your fleet, passenger capacity, and maintenance availability.</p></div><button class="btn btn-primary" @click="open()"><Plus :size="17"/> Add vehicle</button></div><div v-if="success" class="alert alert-success">{{success}}<button @click="success=''"><X :size="16"/></button></div><div v-if="error&&!modal" class="alert alert-error">{{error}}<button @click="error=''"><X :size="16"/></button></div><div class="mini-stats"><div class="mini-stat"><span>Total vehicles</span><strong>{{data.vehicles.length}}</strong></div><div class="mini-stat"><span>Available</span><strong class="text-green">{{data.vehicles.filter(v=>v.status==='Available').length}}</strong></div><div class="mini-stat"><span>In active rides</span><strong class="text-blue">{{data.bookings.filter(b=>b.status==='In Progress'&&b.vehicleId).length}}</strong></div><div class="mini-stat"><span>Maintenance</span><strong class="text-amber">{{data.vehicles.filter(v=>v.status==='Maintenance').length}}</strong></div></div><div class="list-toolbar"><div class="search-field"><Search :size="17"/><input v-model="search" placeholder="Search plate, model, type…"/></div><span class="results-count">{{rows.length}} vehicles</span></div><div class="vehicle-grid"><article v-for="v in rows" :key="v.id" class="vehicle-card"><div class="vehicle-art"><div class="vehicle-type-icon"><CarFront :size="40" stroke-width="1.3"/></div><span class="status-pill" :class="v.status.toLowerCase().replace(' ','-')">{{v.status}}</span></div><div class="vehicle-card-body"><div class="vehicle-type">{{v.type}}</div><h3>{{v.model}}</h3><div class="vehicle-details"><div><Hash :size="15"/><span>{{v.plate}}</span></div><div><Users :size="15"/><span>{{v.capacity}} passenger seats</span></div></div><div class="vehicle-card-footer"><span>Added {{new Date(v.createdAt).toLocaleDateString()}}</span><div class="action-row"><button class="mini-action" @click="open(v)" title="Edit vehicle"><Pencil :size="15"/></button><button class="mini-action danger-action" @click="remove(v)" title="Remove vehicle"><Trash2 :size="15"/></button></div></div></div></article><div v-if="!rows.length" class="empty-state grid-empty"><CarFront :size="32"/><strong>No vehicles found</strong><p>Add a vehicle or change your search.</p></div></div><div v-if="modal" class="modal-backdrop" @click.self="modal=false"><section class="modal-card"><div class="modal-heading"><div><div class="eyebrow">FLEET DIRECTORY</div><h2>{{editing?'Edit vehicle':'Add a vehicle'}}</h2><p class="muted">Register vehicle details and availability.</p></div><button class="icon-button" @click="modal=false"><X/></button></div><form class="form-stack" @submit.prevent="save"><div class="form-grid"><label>Plate number<input v-model.trim="form.plate" required placeholder="ABC-1234"/></label><label>Vehicle model<input v-model.trim="form.model" required placeholder="Toyota Vios"/></label></div><div class="form-grid"><label>Vehicle type<select v-model="form.type"><option>Sedan</option><option>Hatchback</option><option>MPV</option><option>SUV</option><option>Van</option></select></label><label>Passenger capacity<input v-model.number="form.capacity" type="number" min="1" max="15" required/></label></div><label>Status<select v-model="form.status"><option>Available</option><option>Maintenance</option></select></label><p v-if="error" class="form-error">{{error}}</p><div class="modal-actions"><button type="button" class="btn btn-secondary" @click="modal=false">Cancel</button><button class="btn btn-primary" type="submit" :disabled="saving"><Check :size="16"/> {{ saving ? 'Saving…' : 'Save vehicle' }}</button></div></form></section></div></template>